    {"id": 1, "claim": "The medieval English economy was based on feudalism, a system defined by hierarchical social and economic obligations rather than free market exchange.", "evidence": "Historical consensus on the structure of medieval European society, where land tenure and labor services (corvée) were the primary modes of economic interaction between lords and peasants.", "weight": 1.0, "depends_on": []},
    {"id": 2, "claim": "Peasants were legally bound to the land and owed specific dues, rents, and labor services to their lords, leaving them with little to no bargaining power.", "evidence": "Legal codes and manorial court records from the period show that peasants (serfs and villeins) could not freely choose their employment or negotiate terms; their obligations were fixed by custom and law.", "weight": 0.9, "depends_on": [1]},
    {"id": 3, "claim": "The concept of 'fair trade' implies voluntary exchange between independent parties with equal or near-equal negotiating power and adherence to modern ethical standards of equity.", "evidence": "Definition of fair trade in economic and ethical contexts, which contrasts with coerced or structurally unequal exchanges.", "weight": 0.8, "depends_on": []},
    {"id": 4, "claim": "Because the relationship was coercive and structurally unequal, the exchanges between lords and peasants did not meet the criteria of voluntary, equitable trade.", "evidence": "The lack of consent and the extraction of surplus value by the lord through mandatory services and rents characterize the relationship as exploitative rather than fair trade.", "weight": 1.0, "depends_on": [2, 3]},
    {"id": 5, "claim": "Therefore, medieval English lords did not engage in fair trade with peasants.", "evidence": "Synthesis of the structural inequality and the definition of fair trade.", "weight": 1.0, "depends_on": [4]}
